/* Opacity Slider — KWin scripted effect.
 *
 * This file is REGENERATED by the Opacity Slider tray app on every change:
 * it embeds the current per-window / global opacity state as a JSON literal
 * below, then the app reloads the effect via D-Bus so the new state applies.
 *
 * A persistent opacity is a long-running Effect animation: KWin only keeps a
 * window's real appearance during an active animation, so the animation is
 * re-armed here whenever a window appears and whenever the app pushes a new
 * state.
 *
 * State shape: { "opacity": <0..100>, "overrides": { "<caption>": <0..100> },
 *                "transition": <ms> }
 *   - opacity is the default applied to every normal window (100 = opaque)
 *   - overrides are per-window values keyed by KWin caption (win over global)
 *
 * Caption is the only stable shared identity between the tray app's window
 * list and this effect.
 */

/*global effect, effects, animate, set, cancel, print */

"use strict";

var STATE = __STATE__;

var holds = {};   // caption -> set() animation id(s)
var active = {};  // caption -> current target pct (only ever < 100)

function targetFor(w) {
    if (STATE.overrides && Object.prototype.hasOwnProperty.call(STATE.overrides, w.caption)) {
        return Number(STATE.overrides[w.caption]);
    }
    return Number(STATE.opacity);
}

function stopHeld(w) {
    if (holds[w.caption] !== undefined) {
        cancel(holds[w.caption]);
        delete holds[w.caption];
    }
}

function apply(w) {
    var pct = targetFor(w);
    if (!(w.managed && w.normalWindow && w.caption)) {
        return;
    }
    stopHeld(w);

    if (pct >= 100) {
        if (active[w.caption] !== undefined) {
            // Release back to fully opaque with the configured transition.
            animate({
                window: w,
                duration: STATE.transition,
                animations: [{ type: Effect.Opacity, to: 1.0, from: w.opacity }]
            });
        }
        delete active[w.caption];
        return;
    }

    var to = Math.max(0.05, pct / 100);
    holds[w.caption] = set({
        window: w,
        duration: STATE.transition,
        animations: [{ type: Effect.Opacity, to: to, from: w.opacity }]
    });
    active[w.caption] = pct;
}

function refresh() {
    var wins = effects.stackingOrder || [];
    for (var i = 0; i < wins.length; i++) {
        apply(wins[i]);
    }
}

effects.windowAdded.connect(function (w) {
    apply(w);
});

effects.windowClosed.connect(function (w) {
    stopHeld(w);
    delete active[w.caption];
});

refresh();
print("opacity-slider ready state=" + JSON.stringify(STATE));